-- SQL Server login for the stored credentials of the report data source "Retail".
-- Run against RetailLab with sqlcmd; ReaderLogin and ReaderPassword come from the
-- environment (sqlcmd scripting variables), the password is generated by the caller.
-- tests/test_mssql.py runs only the numbered scripts, so this file stays out of the Linux tests.
IF SUSER_ID(N'$(ReaderLogin)') IS NULL
    CREATE LOGIN [$(ReaderLogin)] WITH PASSWORD = N'$(ReaderPassword)', DEFAULT_DATABASE = RetailLab, CHECK_POLICY = ON;
GO
IF USER_ID(N'$(ReaderLogin)') IS NULL
    CREATE USER [$(ReaderLogin)] FOR LOGIN [$(ReaderLogin)];
GO
ALTER ROLE db_datareader ADD MEMBER [$(ReaderLogin)];
GRANT EXECUTE ON SCHEMA::dbo TO [$(ReaderLogin)];
GO
